import {ApiSession} from '/shared/session.mjs';
import {emptyState,validateState,profile,courseLessons,nextLesson,streak,completeLesson,totalXP,dailyMinutes,dayKey,compareTranscript,speechLocale,lessonQuestions,gradeLesson} from '/shared/learning.mjs';
import {AccountStore,mergeProgress,safeStorage} from '/shared/accounts.mjs';
import {validateCatalog} from '/shared/schema.mjs';
import {ParentGate,recoverParentAccess} from '/shared/parent.mjs';
const deviceStorage=safeStorage();
const bootstrapClient=new ApiSession({getSession:()=>null,setSession:()=>false});
let catalog, config={};
try{catalog=validateCatalog(JSON.parse(deviceStorage.getItem('ilmigo-catalog-v2')));}catch{}
try{const bundled=validateCatalog(await bootstrapClient.request('/shared/catalog.json'));if(!catalog||(bundled.revision||1)>(catalog.revision||1))catalog=bundled;}catch{}
if(!catalog){document.querySelector('#app').textContent='ILMIGO could not load. Reconnect to download your lesson library.';throw Error('Catalog unavailable');}
try{config=await bootstrapClient.request('/api/config');}catch{}
try{const remote=validateCatalog(await bootstrapClient.request('/api/catalog'));if((remote.revision||1)>=(catalog.revision||1)){catalog=remote;deviceStorage.setItem('ilmigo-catalog-v2',JSON.stringify(catalog));}}catch{}
let profileSwitchVersion=0;
let page='home',filter='',languageFilter='all',lessonRun=null,ticker=null,recognition=null,auth=null;
try{const saved=JSON.parse(sessionStorage.getItem('ilmigo-auth'));if(saved?.userId&&saved?.access_token)auth=saved;}catch{}
const sessionClient=new ApiSession({getSession:()=>auth,setSession:(next,expected)=>{if(auth!==expected)return false;Object.assign(auth,next);persistAuth();return true;}});
const accounts=new AccountStore(deviceStorage);
let state=accounts.open(auth?.userId||null);
if(auth&&profile(state).kind==='child'&&auth.scope!=='child'){auth=null;persistAuth();}
if(auth?.scope==='child'){const bound=state.profiles.find(pr=>pr.kind==='child'&&pr.cloudId===auth.childProfileId);if(bound)state.active=bound.id;else{auth=null;persistAuth();}}
if(config.subscription?.enabled){catalog={...catalog,lessons:[]};try{deviceStorage.setItem('ilmigo-catalog-v2',JSON.stringify(catalog));}catch{/* Public metadata remains in memory if device storage is full. */}if(auth){try{catalog=validateCatalog(await api('/api/member-catalog'));}catch{/* Stay at public metadata until trial or purchase is verified. */}}}
function parentGate(){return new ParentGate(deviceStorage,`${accounts.key()}:parent`);}
async function ensureParentPin(){try{const gate=parentGate();if(gate.configured)return true;if(!globalThis.crypto?.subtle)throw Error('Parent PIN requires a secure browser. Open ILMIGO using HTTPS or a supported local file browser.');const pin=prompt(tr('Set a parent PIN (6–12 digits). Keep it private; it protects adult profile access on this device.','والدین کے لیے ۶ سے ۱۲ ہندسوں کا پن بنائیں۔ اسے خفیہ رکھیں۔'));if(pin===null)return false;if(prompt(tr('Confirm your parent PIN.','والدین کے پن کی تصدیق کریں۔'))!==pin)throw Error(tr('PINs do not match.','پن ایک جیسے نہیں ہیں۔'));await gate.setup(pin);return true;}catch(e){toast(e.message||'Parent PIN needs a supported secure browser.');return false;}}
async function unlockParent(){try{const pin=prompt(tr('Enter the parent PIN to open an adult profile.','بالغ پروفائل کھولنے کے لیے والدین کا پن دیں۔'));if(pin===null)return false;const ok=await parentGate().verify(pin);if(!ok)toast(tr('Incorrect parent PIN.','والدین کا پن غلط ہے۔'));return ok;}catch(e){toast(e.message);return false;}}
const root=document.querySelector('#app'),overlay=document.querySelector('#overlay');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr=(en,ur)=>state.ui==='ur'?ur:en;
const p=()=>profile(state);
const lang=()=>catalog.languages.find(l=>l.id===p().language)||catalog.languages[1];
const flag=c=>[...c].map(x=>String.fromCodePoint(127397+x.charCodeAt(0))).join('');
const names={home:['My learning','میری تعلیم'],languages:['Explore languages','زبانیں دریافت کریں'],path:['Learning path','تعلیمی سفر'],practice:['Speaking studio','بولنے کی مشق'],family:['My space','میری جگہ']};
const paths={home:'M3 10 12 3l9 7v10H3z M9 20v-7h6v7',languages:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c-5 5-5 13 0 18M12 3c5 5 5 13 0 18',path:'M5 4v16M5 6h13l-3 4 3 4H5',practice:'M12 3a3 3 0 0 0-3 3v6a3 3 0 0 0 6 0V6a3 3 0 0 0-3-3M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8',family:'M16 8a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-2a8 8 0 0 1 16 0v2',arrow:'M5 12h14M13 6l6 6-6 6',flame:'M12 3c2 6-4 7 0 11 2-1 3-3 3-5 7 8 3 13-3 13S2 17 6 10c0 4 3 4 3 2-1-3 0-6 3-9',bolt:'m13 2-9 12h7l-1 8 10-13h-7z',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3zM12 6v16',bell:'M6 9a6 6 0 0 1 12 0v7l2 3H4l2-3zM10 22h4',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 6v6l4 2',check:'m5 12 4 4L19 6',sound:'m3 9 5 0 5-5v16l-5-5H3zM17 8q5 4 0 8',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.star}"/></svg>`;}
function robot(){return `<svg class="robot" viewBox="0 0 240 270" xmlns="http://www.w3.org/2000/svg" aria-label="ILMIGO robot teacher" role="img"><defs><linearGradient id="shell" x2=".8" y2="1"><stop stop-color="#fffef4"/><stop offset="1" stop-color="#c8d9ca"/></linearGradient><linearGradient id="shirt" x2="0" y2="1"><stop stop-color="#f5dc94"/><stop offset="1" stop-color="#d7ad52"/></linearGradient><linearGradient id="visor" x2="1" y2="1"><stop stop-color="#26645d"/><stop offset="1" stop-color="#153f3e"/></linearGradient></defs><ellipse cx="122" cy="254" rx="63" ry="9" fill="#709e7e" opacity=".16"/><path d="M120 39V23" stroke="#689083" stroke-width="6"/><circle cx="120" cy="20" r="8" fill="#edcb6f"/><rect x="41" y="70" width="19" height="39" rx="9" fill="#749e8c"/><rect x="180" y="70" width="19" height="39" rx="9" fill="#749e8c"/><rect x="49" y="39" width="142" height="99" rx="37" fill="url(#shell)"/><rect x="62" y="54" width="116" height="65" rx="25" fill="url(#visor)"/><ellipse cx="91" cy="80" rx="9" ry="11" fill="#c3f5b7"/><ellipse cx="150" cy="80" rx="9" ry="11" fill="#c3f5b7"/><circle cx="94" cy="76" r="3" fill="#fff"/><circle cx="153" cy="76" r="3" fill="#fff"/><path d="M108 101q12 12 25 0" fill="none" stroke="#b9ebbd" stroke-width="4" stroke-linecap="round"/><ellipse cx="78" cy="98" rx="8" ry="3" fill="#7ab69b" opacity=".6"/><ellipse cx="162" cy="98" rx="8" ry="3" fill="#7ab69b" opacity=".6"/><rect x="103" y="131" width="35" height="16" rx="7" fill="#7ca293"/><path d="M72 147q48-17 97 0l10 62q-57 17-116 0z" fill="url(#shirt)"/><path d="m72 147-23 30 15 13 22-30m80-13 21 12 23-28" fill="none" stroke="#e3c279" stroke-width="23" stroke-linecap="round"/><path d="m209 129 5-17m-5 17 14-6m-14 6-1-15" stroke="#d5dfd0" stroke-width="8" stroke-linecap="round"/><circle cx="52" cy="184" r="13" fill="url(#shell)"/><path d="m84 215-3 24m74-24 5 24" stroke="#7b9d8f" stroke-width="19" stroke-linecap="round"/><ellipse cx="77" cy="243" rx="22" ry="10" fill="url(#shell)"/><ellipse cx="163" cy="243" rx="22" ry="10" fill="url(#shell)"/><rect x="85" y="164" width="72" height="29" rx="6" fill="#fffbe9" opacity=".8"/><text x="121" y="184" text-anchor="middle" font-family="Arial,sans-serif" font-weight="800" font-size="15" fill="#355a4d">ILMIGO</text><path d="M103 202h36" stroke="#ba984e" opacity=".4" stroke-width="3" stroke-linecap="round"/></svg>`;}
function save(){try{accounts.save(state);return true;}catch{toast(tr('Storage is full. Export your progress from My space.','اسٹوریج بھر گئی ہے۔ اپنی پیش رفت محفوظ کریں۔'));return false;}}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),4500);}
function navigate(to){page=to;closeModal();render();window.scrollTo({top:0,behavior:'smooth'});}
function render(){stopPracticeMedia();document.documentElement.lang=state.ui;document.documentElement.dir=state.ui==='ur'?'rtl':'ltr';const current=p();root.className=state.ui==='ur'?'rtl':'';root.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><img src="/icon.svg" alt=""><span>ILMIGO<small>.</small></span></div><div class="brand-note">DIGITAL ACADEMY</div><nav class="nav" aria-label="Main navigation">${Object.entries(names).map(([id,labels])=>`<button data-nav="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}<span>${esc(tr(...labels))}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="mini-card"><div class="eyebrow">${tr('A little more possibility','سیکھنے کے مزید مواقع')}</div><p>${tr('Build your confidence. One conversation at a time.','ہر گفتگو کے ساتھ اپنا اعتماد بڑھائیں۔')}</p><button data-action="premium">${tr('Discover ILMIGO Plus','ILMIGO Plus دیکھیں')} ↗</button></div><button class="profile-button" data-nav="family"><span class="avatar">${esc(current.name.slice(0,1).toUpperCase())}</span><span>${esc(current.name)}<small>${tr(current.kind==='child'?'Family learner':'Your learning space',current.kind==='child'?'بچے کا پروفائل':'آپ کی تعلیمی جگہ')}</small></span></button></div></aside><div class="main"><header class="topbar"><div class="breadcrumb">${tr('Your space','آپ کی جگہ')} &nbsp; / &nbsp; <strong>${esc(tr(...names[page]))}</strong></div><div class="brand mobile-logo"><img src="/icon.svg" alt=""><span class="academy-wordmark">ILMIGO<small>DIGITAL ACADEMY</small></span></div><div class="top-actions"><button class="language-pill" data-action="switch-language">${flag(lang().country)} ${esc(lang().name)} <span>⌄</span></button><button class="notification" data-action="reminder" aria-label="Lesson reminder">${icon('bell')}</button><button class="avatar" data-nav="family" aria-label="Open profile">${esc(current.name.slice(0,1).toUpperCase())}</button></div></header><main class="content">${({home:home,languages:languagesPage,path:pathPage,practice:practicePage,family:familyPage})[page]()}<footer class="footer"><span>© ${new Date().getFullYear()} ILMIGO DIGITAL ACADEMY · ${tr('Small steps. A bigger world.','چھوٹے قدم، ایک بڑی دنیا۔')}</span><button data-action="privacy">${tr('Privacy & your data','رازداری اور آپ کا ڈیٹا')}</button></footer></main></div></div>`;bind(root);if(page==='languages')bindCatalog();if(page==='practice')bindPractice(root);}
function head(title,sub){return `<div class="page-head"><div><div class="eyebrow">${tr('YOUR NEXT CHAPTER','آپ کا اگلا قدم')}</div><h1>${title}</h1><p>${sub}</p></div><span class="date">${new Date().toLocaleDateString(state.ui==='ur'?'ur-PK':'en-GB',{weekday:'long',day:'numeric',month:'long'})}</span></div>`;}
function levelName(level){const i=['beginner','elementary','intermediate','advanced','professional'].indexOf(level);return tr(['Beginner','Elementary','Intermediate','Advanced','Professional'][i]||level,['ابتدائی','بنیادی','درمیانی','اعلیٰ','پیشہ ورانہ'][i]||level);}
function courseSummary(){return tr('English and Urdu: 20 guided lessons each, across five stages. Original curriculum draft; language/audio review pending. Other 32 languages are coming soon.','انگریزی اور اردو: پانچ مراحل میں بیس بیس رہنمائی والے اسباق۔ اصل نصاب کا مسودہ؛ زبان اور آواز کا جائزہ باقی ہے۔ دوسری ۳۲ زبانیں جلد آئیں گی۔');}
function home(){const current=p(),next=nextLesson(catalog,current),minutes=dailyMinutes(current,catalog),lessons=courseLessons(catalog,current.language);return `${head(tr(`Hello, ${esc(current.name)} <span style="font-size:23px">☀</span>`,`سلام، ${esc(current.name)} ☀`),tr('A little practice today. A world of confidence tomorrow.','آج کی تھوڑی سی مشق، کل کا بھرپور اعتماد۔'))}<div class="dashboard-grid"><div><section class="hero"><div class="hero-copy"><div class="hero-tag">✦ ${tr('YOUR FRIENDLY LANGUAGE COMPANION','آپ کا دوستانہ زبان کا استاد')}</div><h2>${tr('Small steps.<br>Big <em>conversations.</em>','چھوٹے قدم۔<br>بڑی <em>گفتگو۔</em>')}</h2><p>${tr('Hi, I’m ILMIGO! Ready to discover a few new words together? Let’s make today count.','میں ILMIGO ہوں! آئیں آج چند نئے الفاظ سیکھیں اور بولنے کی مشق کریں۔')}</p><button class="primary" data-lesson="${next?.id||''}">${tr('Let’s learn together','آئیں ساتھ سیکھیں')} ${icon('arrow')}</button><span class="hero-meta">${icon('clock')} 30 ${tr('min / day','منٹ روزانہ')}</span></div><div class="robot-scene"><span class="sparkle">✧</span><span class="floating-chip">Hello! 👋</span>${robot()}<span class="floating-chip two" lang="ur" dir="rtl">السلام علیکم</span></div></section><div class="stats"><div class="stat"><div class="stat-icon">${icon('flame')}</div><div><strong>${streak(current.days)} <span style="display:inline;color:inherit;font-size:11px">${tr('days','دن')}</span></strong><span>${tr('Learning streak','مسلسل تعلیم')}</span></div></div><div class="stat"><div class="stat-icon">${icon('bolt')}</div><div><strong>${totalXP(current)} <span style="display:inline;color:inherit;font-size:11px">XP</span></strong><span>${tr('Words in motion','تعلیمی پوائنٹس')}</span></div></div><div class="stat"><div class="stat-icon">${icon('book')}</div><div><strong>${Object.keys(current.completed).length}</strong><span>${tr('Lessons completed','مکمل اسباق')}</span></div></div></div><div class="section-head"><h2>${tr('Pick up where you left off','وہیں سے آگے بڑھیں')}</h2><button data-nav="path">${tr('View learning path','تعلیمی سفر دیکھیں')} ↗</button></div>${next?`<section class="lesson-card"><div class="lesson-inner"><div class="lesson-art">${flag(lang().country)}</div><div class="lesson-info"><small>${esc(lang().name.toUpperCase())} · ${esc(levelName(next.level))}</small><h3>${esc(tr(next.title,next.titleUr))}</h3><p>${esc(tr(next.objective,next.objectiveUr))}</p></div><div class="progress-group"><small>${Object.keys(current.completed).filter(id=>lessons.some(l=>l.id===id)).length} / ${lessons.length} ${tr('lessons','اسباق')}</small><div class="progress"><span style="width:${lessons.filter(l=>current.completed[l.id]).length/lessons.length*100}%"></span></div></div></div><div class="lesson-bottom"><span>${icon('clock')} ${tr('30 min · Reading, listening & speaking','۳۰ منٹ · پڑھنا، سننا اور بولنا')}</span><button data-lesson="${next.id}">${tr(current.sessions[next.id]?'Resume lesson':'Start lesson',current.sessions[next.id]?'سبق جاری رکھیں':'سبق شروع کریں')} →</button></div></section>`:`<div class="empty-state"><h2>${tr('This course is on its way','یہ کورس جلد آئے گا')}</h2><button class="primary" data-nav="languages">${tr('Explore languages','زبانیں دیکھیں')}</button></div>`}<div class="section-head"><h2>${tr('Where will words take you?','الفاظ آپ کو کہاں لے جائیں گے؟')}</h2><button data-nav="languages">${tr('Explore all 34 languages','تمام ۳۴ زبانیں دیکھیں')} ↗</button></div><div class="language-row">${catalog.languages.filter(l=>['ur','tr','ar'].includes(l.id)).map(languageCard).join('')}</div></div><aside class="right-column"><section class="side-card"><div class="daily-header"><h3>${tr('Your daily goal','روزانہ کا ہدف')}</h3>${icon('star')}</div><div class="goal-circle" style="--pct:${minutes/30*100}%"><div><strong>${minutes}<span style="font-size:15px;color:#b0b5a9"> / 30</span></strong><small>${tr('planned minutes completed','مکمل سبق کے منصوبہ بند منٹ')}</small></div></div><p class="daily-note">${tr(minutes?'You showed up. That’s how growth starts.':'Your next 30 minutes could open a new door.',minutes?'آپ نے آج سیکھنے کا وقت نکالا۔':'آج کے ۳۰ منٹ ایک نیا دروازہ کھول سکتے ہیں۔')}</p><div class="week">${week()}</div></section><section class="side-card"><div class="daily-header"><h3>${tr('A plan made for today','آج کا منصوبہ')}</h3><span class="badge">30 ${tr('min','منٹ')}</span></div>${catalog.blocks.map((b,i)=>`<div class="daily-block"><span class="block-icon">${['↺','Aa','▤','◉','✓'][i]}</span><div><strong>${esc(tr(b.title,b.titleUr))}</strong><small>${tr(['Refresh what you know','Make new connections','Bring words to life','Find your voice','Celebrate your progress'][i],['سابقہ علم دہرائیں','نئے الفاظ سیکھیں','پڑھیں اور سمجھیں','اپنی آواز استعمال کریں','اپنی تعلیم جانچیں'][i])}</small></div><span>${b.minutes}m</span></div>`).join('')}</section><section class="quote-card"><p>“${tr('A different language is a different vision of life.','نئی زبان، زندگی کو دیکھنے کا ایک نیا انداز۔')}”</p><small>— Federico Fellini</small></section></aside></div>`;}
function week(){const today=new Date(),start=new Date(today);start.setDate(today.getDate()-((today.getDay()+6)%7));return Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const key=dayKey(d);return `<div class="day ${p().days.includes(key)?'done':''} ${key===dayKey(today)?'today':''}"><b>${p().days.includes(key)?'✓':d.getDate()}</b>${['M','T','W','T','F','S','S'][i]}</div>`;}).join('');}
function languageCard(l){return `<button class="lang-card" data-language="${l.id}"><span class="flag">${flag(l.country)}</span><h3>${esc(l.name)}</h3><small lang="${l.id}" dir="${l.direction}">${esc(l.native)}</small><div><span class="tag">${l.status==='sample'?tr('Curriculum draft','نصاب کا مسودہ'):tr('Coming soon','جلد آرہا ہے')}</span></div></button>`;}
function languagesPage(){return `${head(tr('A world waiting to be understood','سمجھنے کے لیے ایک پوری دنیا'),tr('34 languages. Countless connections. Find your next beginning.','۳۴ زبانیں، بے شمار تعلقات۔ اپنے اگلے سفر کا آغاز کریں۔'))}<div class="note">${courseSummary()}</div><div class="catalog-tools"><input id="search" aria-label="Search languages" placeholder="${tr('Search a language…','زبان تلاش کریں…')}" value="${esc(filter)}"><select id="filter" aria-label="Filter languages"><option value="all">${tr('All languages','تمام زبانیں')}</option><option value="available">${tr('Available samples','دستیاب نمونے')}</option><option value="pakistan">${tr('Languages of Pakistan','پاکستان کی زبانیں')}</option></select></div><div class="catalog-grid" id="catalog-grid">${filteredLanguages()}</div>`;}
function filteredLanguages(){const found=catalog.languages.filter(l=>(`${l.name} ${l.native} ${l.variants.join(' ')}`.toLocaleLowerCase().includes(filter.toLocaleLowerCase()))&&(languageFilter==='all'||languageFilter==='available'&&l.status==='sample'||languageFilter==='pakistan'&&l.country==='PK'));return found.length?found.map(languageCard).join(''):`<p class="help">${tr('No matching languages. Try a different search.','کوئی زبان نہیں ملی۔ دوبارہ تلاش کریں۔')}</p>`;}
function bindCatalog(){const input=document.querySelector('#search'),select=document.querySelector('#filter');select.value=languageFilter;function update(){const grid=document.querySelector('#catalog-grid');grid.innerHTML=filteredLanguages();bind(grid);}input.oninput=()=>{filter=input.value;update();};select.onchange=()=>{languageFilter=select.value;update();};}
function pathPage(){const all=courseLessons(catalog,p().language);return `${head(tr('Your path to possibility','آپ کا تعلیمی سفر'),tr('Build skills from first words to workplace communication.','پہلے الفاظ سے کام کی جگہ کی گفتگو تک مہارت بڑھائیں۔'))}<div class="path-layout"><div class="note">${courseSummary()}<br>${tr('Completion records practice, not certified proficiency. Follow the recommended order or revisit a topic.','تکمیل مشق کا ریکارڈ ہے، مہارت کی سند نہیں۔ تجویز کردہ ترتیب پر چلیں یا موضوع دہرائیں۔')}</div>${catalog.levels.map((level,i)=>{const units=all.filter(l=>l.level===level);return `<section class="level"><div class="level-title"><h2>${i+1}. ${esc(levelName(level))}</h2><span class="badge">${units.filter(l=>p().completed[l.id]).length} / ${units.length}</span></div>${units.length?units.map((l,j)=>`<button class="path-lesson" data-lesson="${l.id}"><span class="step-number">${p().completed[l.id]?'✓':j+1}</span><span><strong>${esc(tr(l.title,l.titleUr))}</strong><small>${esc(tr(l.objective,l.objectiveUr))}</small></span><span>${icon('arrow')}</span></button>`).join(''):`<p class="help">${tr('This collection has no lessons in this stage yet.','اس مجموعے میں اس مرحلے کے اسباق ابھی نہیں ہیں۔')}</p>`}</section>`;}).join('')}</div>`;}

function practicePage(){const l=nextLesson(catalog,p());return `${head(tr('Find your voice','اپنی آواز تلاش کریں'),tr('Listen. Try it out loud. Grow a little more confident.','سنیں، اونچی آواز میں دہرائیں، اعتماد بڑھائیں۔'))}<div class="practice-layout"><div class="practice-robot">${robot()}<h2>${tr('Your patient practice partner','آپ کا پُرسکون مشق کا ساتھی')}</h2><p>${tr('Take your time. Every attempt is a step forward.','آرام سے سیکھیں۔ ہر کوشش آپ کو آگے لے جاتی ہے۔')}</p></div><div class="practice-panel"><h3>${tr('Try this phrase','یہ جملہ بول کر دیکھیں')}</h3><div class="target-text" dir="${lang().direction}">${esc(l?.speaking||'Hello!')}</div><div class="button-row"><button class="secondary" data-speak="${esc(l?.speaking||'Hello!')}">${icon('sound')} ${tr('Listen','سنیں')}</button><button class="primary green" id="record">${icon('practice')} ${tr('Say it','بولیں')}</button></div><label for="transcript">${tr('Your words (or type your answer)','آپ کے الفاظ (یا جواب لکھیں)')}</label><input id="transcript" dir="${lang().direction}" placeholder="${tr('Your transcript appears here…','آپ کے الفاظ یہاں آئیں گے…')}"><div class="button-row"><button class="secondary" id="check-words">${tr('Compare words','الفاظ ملائیں')}</button><button class="primary" id="ask-ai">${tr('Ask ILMIGO for feedback','ILMIGO سے رہنمائی لیں')}</button></div><p class="help">${tr('Word matching is a practice aid, not a pronunciation score. Device voices and recognition depend on browser support. AI feedback needs a connected adult account and configured service.','الفاظ کا موازنہ تلفظ کا اسکور نہیں ہے۔ آواز اور شناخت براؤزر پر منحصر ہیں۔ AI کے لیے منسلک اکاؤنٹ اور سروس ضروری ہے۔')}</p><div id="speech-feedback" aria-live="polite"></div><h3>${tr("Talk with ILMIGO","ILMIGO سے گفتگو کریں")}</h3><p class="help">${tr("Use the same microphone or text box above. Replies can be played using your installed device voice. Conversations stay in this page memory and use the same daily AI allowance.","اوپر مائیک یا جواب کا خانہ استعمال کریں۔ جواب آلے کی آواز میں سن سکتے ہیں۔ گفتگو اسی صفحے کی میموری میں رہتی ہے اور روزانہ AI حد استعمال کرتی ہے۔")}</p><div class="button-row"><button class="primary" id="conversation-send">${tr("Send conversation turn","گفتگو کا جواب بھیجیں")}</button><button class="secondary" id="conversation-reset">${tr("New conversation","نئی گفتگو")}</button></div><div id="conversation-log" aria-live="polite"></div><div class="note">${tr('Browser speech recognition may send audio to your device/browser provider. Audio is not saved by ILMIGO. Children use listen-and-repeat on this device.','براؤزر آواز کی شناخت کے لیے آڈیو اپنے فراہم کنندہ کو بھیج سکتا ہے۔ ILMIGO آڈیو محفوظ نہیں کرتا۔ بچے سن کر دہرائیں۔')}</div></div></div>`;}
function bindPractice(container){bindConversation(container);const target=nextLesson(catalog,p())?.speaking||'Hello!';container.querySelector('#record')?.addEventListener('click',()=>record(container.querySelector('#transcript'),container.querySelector('#record')));container.querySelector('#check-words')?.addEventListener('click',()=>{const actual=container.querySelector('#transcript').value;if(!actual.trim())return toast(tr('Say or type the phrase first.','پہلے جملہ بولیں یا لکھیں۔'));const result=compareTranscript(target,actual);container.querySelector('#speech-feedback').innerHTML=`<div class="feedback">${tr(`${result.matched} of ${result.total} target words found.`,`${result.total} میں سے ${result.matched} الفاظ ملے۔`)} ${result.missing.length?tr('Try these words again: ','یہ الفاظ پھر دہرائیں: ')+esc(result.missing.join(', ')):tr('Nice work! Try saying it naturally.','بہت خوب! اب قدرتی انداز میں بولیں۔')}</div>`;});container.querySelector('#ask-ai')?.addEventListener('click',async e=>{if(p().kind==='child')return toast('Ask a parent to use AI feedback.');if(!auth)return loginModal();if(p().kind==='child')return toast(tr('Live AI is not enabled for child profiles.','بچوں کے لیے براہ راست AI فعال نہیں ہے۔'));const transcript=container.querySelector('#transcript').value.trim();if(!transcript)return toast(tr('Say or type your answer first.','پہلے اپنا جواب دیں۔'));const learner=p(),snapshot=state,owner=auth.userId,output=container.querySelector('#speech-feedback');e.currentTarget.disabled=true;try{const result=await api('/api/speaking',{profileId:learner.cloudId,lessonId:nextLesson(catalog,learner).id,transcript,ui:state.ui});if(state!==snapshot||p()!==learner||auth?.userId!==owner||!output?.isConnected)return;output.textContent=result.feedback;}catch(err){toast(err.message);}finally{const b=container.querySelector('#ask-ai');if(b)b.disabled=false;}});}
function record(input,button){if(p().kind==='child')return toast(tr('For child profiles, listen and repeat with a parent.','بچے والدین کے ساتھ سن کر دہرائیں۔'));const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech)return toast(tr('Speech recognition is not supported here. Type your answer instead.','یہاں آواز کی شناخت دستیاب نہیں؛ جواب لکھیں۔'));if(recognition){recognition.stop();recognition=null;button.textContent=tr('Say it','بولیں');return;}recognition=new Speech();recognition.lang=speechLocale(p().language);recognition.interimResults=false;button.textContent=tr('Listening… tap to stop','سن رہا ہوں… روکیں');recognition.onresult=e=>{input.value=e.results[0][0].transcript;};recognition.onerror=e=>toast(tr(`Microphone unavailable (${e.error}). You can type your answer.`,`مائیک دستیاب نہیں (${e.error})۔ جواب لکھیں۔`));recognition.onend=()=>{recognition=null;button.textContent=tr('Say it','بولیں');};try{recognition.start();}catch{recognition=null;button.textContent=tr('Say it','بولیں');toast('Microphone unavailable.');}}
function speak(text){if(!('speechSynthesis'in window))return toast(tr('Audio is unavailable on this device.','اس آلے پر آواز دستیاب نہیں۔'));const code=p().language;const voices=speechSynthesis.getVoices(),voice=voices.find(v=>v.lang.startsWith(code));if(!voice&&voices.length)return toast(tr(`No ${lang().name} voice is installed. Use the written transliteration for now.`,`${lang().native} کی آواز نصب نہیں۔ تحریری تلفظ استعمال کریں۔`));speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=speechLocale(code);if(voice)u.voice=voice;u.rate=.8;u.onerror=()=>toast(tr('Could not play audio. Check installed device voices.','آواز نہیں چل سکی۔ آلے کی آوازیں چیک کریں۔'));speechSynthesis.speak(u);}
function familyPage(){return `${head(tr('Make yourself at home','آپ کی اپنی جگہ'),tr('Your goals, your progress, your own pace.','آپ کے مقاصد، آپ کی پیش رفت، آپ کی رفتار۔'))}<div class="settings-grid"><section class="settings-card"><h2>${tr('Learning profiles','تعلیمی پروفائل')}</h2>${p().kind==='child'&&accounts.owner?`<button class="secondary" data-action="recover-parent">${tr('Parent: recover access with email','والدین: ای میل سے رسائی بحال کریں')}</button>`:''}<p>${tr('Progress stays separate for every learner. Local child profiles are managed by the adult using this device. Cloud child profiles require an adult account.','ہر سیکھنے والے کی پیش رفت الگ ہے۔ مقامی بچوں کے پروفائل والدین اس آلے پر چلاتے ہیں۔')}</p>${state.profiles.map(pr=>`<div class="profile-row"><div><strong>${esc(pr.name)}</strong><small>${pr.kind==='child'?tr('Child · parent managed','بچہ · والدین کی نگرانی'):tr('Adult learner','بالغ سیکھنے والا')} · ${Object.keys(pr.completed).length} ${tr('lessons','اسباق')}</small></div><button data-profile="${pr.id}" class="switch ${pr.id===state.active?'selected':''}">${pr.id===state.active?tr('Active','فعال'):tr('Switch','منتخب کریں')}</button></div>`).join('')}<div class="button-row"><button class="secondary" data-action="add-profile">+ ${tr('Add child profile','بچے کا پروفائل شامل کریں')}</button><button class="secondary" data-action="rename">${tr('Edit name','نام بدلیں')}</button>${auth&&p().kind!=='child'?`<button class="secondary" data-action="revoke-child-sessions">${tr('End child cloud sessions','بچوں کے کلاؤڈ سیشن ختم کریں')}</button>`:''}</div><p class="help">${tr('An adult PIN protects profile switching on this device. It is not verified parent identity; keep the device supervised.','مقامی پروفائل حفاظتی لاک نہیں ہیں۔ مشترکہ آلے پر نگرانی اور ڈیوائس لاک استعمال کریں۔')}</p></section><section class="settings-card"><h2>${tr('Make it yours','اپنی پسند منتخب کریں')}</h2><label for="ui-language">${tr('Explanation language','سمجھانے کی زبان')}</label><select id="ui-language"><option value="en" ${state.ui==='en'?'selected':''}>English</option><option value="ur" ${state.ui==='ur'?'selected':''}>اردو</option></select><label for="learning-goal">${tr('Learning goal','سیکھنے کا مقصد')}</label><select id="learning-goal" ${auth?.scope==='child'?'disabled':''}>${['Everyday conversation','Travel & connections','School & study','Work & interviews'].map((g,i)=>`<option value="${g}" ${p().goal===g?'selected':''}>${tr(g,['روزمرہ کی گفتگو','سفر اور تعلقات','سکول اور تعلیم','کام اور انٹرویو'][i])}</option>`).join('')}</select><div class="button-row"><button class="secondary" data-action="reminder">${icon('bell')} ${tr('Set daily reminder','روزانہ یاددہانی')}</button></div><p class="help">${tr('Reminders are a downloadable calendar event. They work without keeping ILMIGO open.','یاددہانی کیلنڈر ایونٹ کے طور پر ڈاؤن لوڈ ہوتی ہے۔')}</p></section><section class="settings-card"><h2>${tr('Your progress, wherever you go','آپ کی پیش رفت، آپ کے ساتھ')}</h2><p>${auth?tr('Signed in. Use Sync now to back up profiles and completed lessons.','سائن ان ہیں۔ پروفائل اور اسباق محفوظ کرنے کے لیے سنک کریں۔'):tr('Guest progress is stored on this device. Sign in to connect cloud sync, or export a backup.','مہمان کی پیش رفت اس آلے پر محفوظ ہوتی ہے۔ کلاؤڈ کے لیے سائن ان کریں یا بیک اپ لیں۔')}</p><div class="button-row">${auth?`<button class="primary" data-action="sync">${tr('Sync now','اب سنک کریں')}</button><button class="secondary" data-action="import-guest">${tr('Import guest progress','مہمان کی پیش رفت شامل کریں')}</button><button class="secondary" data-action="logout">${tr('Sign out','سائن آؤٹ')}</button>`:`<button class="primary" data-action="login">${tr('Sign in with email','ای میل سے سائن ان')}</button>`}<button class="secondary" data-action="export">${tr('Export backup','بیک اپ لیں')}</button><button class="secondary" data-action="import">${tr('Import backup','بیک اپ بحال کریں')}</button></div><input type="file" id="import-file" accept="application/json" hidden><p class="help">${tr('Cloud services are inactive until the app owner supplies Supabase configuration.','کلاؤڈ سروسز مالک کی Supabase ترتیب کے بعد فعال ہوں گی۔')}</p></section><section class="settings-card"><h2>ILMIGO Plus ✦</h2><p>${tr('Advanced courses and daily AI conversation are planned for Plus. Purchases are not enabled in this local build.','اعلیٰ کورس اور روزانہ AI گفتگو Plus میں ہوں گے۔ اس مقامی ورژن میں خریداری فعال نہیں ہے۔')}</p><div class="button-row"><button class="secondary" data-action="premium">${tr('See what’s coming','مزید دیکھیں')}</button><button class="secondary" data-action="privacy">${tr('Manage my data','اپنا ڈیٹا سنبھالیں')}</button></div></section></div>`;}
function bind(scope){scope.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));scope.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>startLesson(b.dataset.lesson));scope.querySelectorAll('[data-language]').forEach(b=>b.onclick=()=>chooseLanguage(b.dataset.language));scope.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(b.dataset.speak));scope.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>switchProfile(b.dataset.profile).catch(error=>toast(error.message)));scope.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions[b.dataset.action]?.());scope.querySelector('#ui-language')?.addEventListener('change',e=>{state.ui=e.target.value;save();render();});scope.querySelector('#learning-goal')?.addEventListener('change',e=>{p().goal=e.target.value;save();});scope.querySelector('#import-file')?.addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error();const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.profiles)||!data.profiles.length||data.profiles.length>12)throw Error();if(p().kind==='child')return toast('A parent must import backups.');if(data.ownerId&&data.ownerId!==accounts.owner)throw Error('Backup belongs to another account.');if(data.profiles.some(pr=>pr.kind==='child')&&!await ensureParentPin())return;state=validateState(data);state.ownerId=accounts.owner;for(const pr of state.profiles)delete pr.cloudId;save();render();toast(tr('Backup restored.','بیک اپ بحال ہو گیا۔'));}catch{toast(tr('That backup could not be read. Your progress is unchanged.','بیک اپ نہیں پڑھا جا سکا۔'));}});}
function modal(html,wide=false){overlay.innerHTML=`<div class="overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="ILMIGO"><button class="close-modal" aria-label="Close">×</button>${html}</section></div>`;overlay.querySelector('.close-modal').onclick=closeModal;overlay.querySelector('.overlay').onclick=e=>{if(e.target.classList.contains('overlay'))closeModal();};bind(overlay);setTimeout(()=>overlay.querySelector('button,input,select')?.focus(),30);}
function closeModal(){if(ticker)clearInterval(ticker);ticker=null;stopPracticeMedia();overlay.innerHTML='';lessonRun=null;}
// Keep keyboard focus inside active dialogs.
window.addEventListener('keydown',e=>{if(!overlay.firstChild)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const els=[...overlay.querySelectorAll('button:not(:disabled),input,select,a[href]')].filter(el=>el.offsetParent!==null);if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
function chooseLanguage(id){if(auth?.scope==='child')return toast(tr('Ask a parent to change this child’s course.','بچے کا کورس بدلنے کے لیے والدین سے کہیں۔'));const l=catalog.languages.find(x=>x.id===id);if(!l)return;if(l.status==='coming_soon'){modal(`<div class="eyebrow">${flag(l.country)} ${esc(l.name)}</div><h2>${tr('A new beginning is on its way','ایک نیا آغاز جلد آئے گا')}</h2><p>${tr('This course is in development. Lessons will be released after language review and audio checks.','یہ کورس تیاری میں ہے۔ زبان اور آواز کے جائزے کے بعد اسباق جاری ہوں گے۔')}${l.id==='ps'?tr(' Swabi Pashto will be a regional practice track.',' سوابی پشتو علاقائی مشق میں شامل ہوگی۔'):''}</p><button class="primary" data-action="close">${tr('Keep exploring','مزید زبانیں دیکھیں')}</button>`);return;}p().language=id;save();closeModal();render();toast(tr(`You’re learning ${l.name}.`,`${l.name} منتخب کر لی گئی۔`));}
async function startLesson(id){if(config.subscription?.enabled){if(!auth)return loginModal();const owner=auth.userId,snapshot=state,learner=p();try{const status=await api('/api/entitlements');if(auth?.userId!==owner||state!==snapshot||p()!==learner)return;if(!status.access)return membershipModal();}catch(error){if(auth?.userId===owner&&state===snapshot)toast(error.message);return;}}const lesson=catalog.lessons.find(l=>l.id===id);if(!lesson)return navigate('languages');closeModal();const saved=p().sessions[id];lessonRun={lesson,index:Math.min(4,Math.max(0,Number(saved?.index)||0)),seconds:Math.max(0,Number(saved?.seconds)||0),answers:Array.isArray(saved?.answers)?saved.answers:[],writing:typeof saved?.writing==='string'?saved.writing:(p().drafts?.[id]||''),wrong:false};showBlock();ticker=setInterval(()=>{if(!lessonRun||document.hidden)return;lessonRun.seconds++;persistRun(false);if(lessonRun.seconds%5===0)save();const el=document.querySelector('#lesson-clock');if(el)el.textContent=formatTime(lessonRun.seconds);},1000);}
function persistRun(flush=true){if(!lessonRun)return;const r=lessonRun;p().sessions[r.lesson.id]={index:r.index,seconds:r.seconds,answers:r.answers,writing:r.writing};if(flush)save();}
function formatTime(seconds){return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;}
function showBlock(){const run=lessonRun;if(!run)return;const {lesson:l,index:i}=run,b=catalog.blocks[i],pr=p();let content='';if(i===0){const previous=courseLessons(catalog,l.language).filter(x=>pr.completed[x.id]&&x.id!==l.id).at(-1);content=`<p class="help">${tr(previous?'Recall these words from your last completed lesson. Say each one aloud.':'Your first warm-up: read these phrases and notice the sounds. Take five minutes at your own pace.',previous?'پچھلے مکمل سبق کے الفاظ یاد کریں۔ ہر لفظ بولیں۔':'ان جملوں کو پڑھیں اور آوازوں پر غور کریں۔ آرام سے پانچ منٹ مشق کریں۔')}</p>${(previous||l).words.slice(0,3).map(word).join('')}`;}if(i===1)content=`<p class="help">${esc(tr(l.objective,l.objectiveUr))}</p>${l.words.map(word).join('')}${l.grammar?`<div class="note"><strong>${tr('Pattern & usage','ساخت اور استعمال')}</strong><br>${esc(tr(l.grammar.en,l.grammar.ur))}</div>`:''}`;if(i===2)content=`<div class="read-text" dir="${lang().direction}">${esc(l.reading)}</div><button class="secondary" data-speak="${esc(l.reading)}">${icon('sound')} ${tr('Listen & read along','سنیں اور ساتھ پڑھیں')}</button>${l.language==='en'&&state.ui==='ur'?`<p class="help" style="margin-top:17px">${esc(l.readingUr)}</p>`:''}<p class="help" style="margin-top:16px">${tr('Read slowly, then repeat without looking. Use the suggested seven minutes to practise.','آہستہ پڑھیں، پھر بغیر دیکھے دہرائیں۔ سات منٹ مشق کریں۔')}</p>`;if(i===2&&l.language==='ur'&&state.ui==='en'&&l.translation)content+=`<p class="help" style="margin-top:16px">${esc(l.translation.en)}</p>`;if(i===2&&l.dialogue)content+=`<h3 style="margin-top:20px">${tr('Practise both sides','دونوں کرداروں کی مشق کریں')}</h3>${l.dialogue.map(d=>`<div class="word"><div><strong dir="${lang().direction}">${esc(d.speaker)}: ${esc(d.text)}</strong><small>${esc(d.translation)}</small></div><button data-speak="${esc(d.text)}" aria-label="Listen to dialogue">${icon('sound')}</button></div>`).join('')}`;if(i===3)content=`<div class="target-text" dir="${lang().direction}">${esc(l.speaking)}</div><div class="button-row"><button class="secondary" data-speak="${esc(l.speaking)}">${icon('sound')} ${tr('Listen','سنیں')}</button><button class="primary" id="lesson-record">${icon('practice')} ${tr('Try speaking','بولنے کی کوشش کریں')}</button></div><input id="lesson-transcript" aria-label="Speech transcript" placeholder="${tr('Or type the phrase here…','یا جملہ یہاں لکھیں…')}" dir="${lang().direction}"><p class="help" style="margin-top:15px">${tr('Repeat a few times. Recording is optional; word matching is available in Speaking studio.','کئی بار دہرائیں۔ ریکارڈ کرنا اختیاری ہے۔')}</p>`;if(i===3&&l.writing)content+=`<div class="note"><strong>${tr('Speaking & writing task','بولنے اور لکھنے کی مشق')}</strong><br>${esc(tr(l.writing.en,l.writing.ur))}</div><label for="writing-response">${tr('Your draft (saved on this device)','آپ کا مسودہ (اس آلے پر محفوظ)')}</label><textarea id="writing-response" rows="6" maxlength="4000" style="width:100%;padding:16px;border:1px solid #d6dfd3;border-radius:12px;font:inherit">${esc(run.writing)}</textarea><p class="help">${tr('Self-review only; ILMIGO does not automatically grade this writing or certify speaking.','یہ خود جائزہ لینے کی مشق ہے؛ تحریر یا گفتگو کی خودکار سند نہیں۔')}</p>${(l.rubric?.[state.ui]||[]).map(r=>`<p class="help">□ ${esc(r)}</p>`).join('')}`;if(i===4)content=`${lessonQuestions(l).map((q,j)=>`<h3 style="font-size:17px;margin:22px 0">${j+1}. ${esc(tr(q.question,q.questionUr))}</h3>${q.options.map(a=>`<button class="answer ${run.answers[j]===a?'selected':''}" data-answer-index="${j}" data-answer="${esc(a)}">${esc(a)}</button>`).join('')}`).join('')}${run.wrong?`<div class="note">${tr('Some answers need another look. Review the reading and try again.','کچھ جواب دوبارہ دیکھیں۔ متن دہرائیں اور پھر کوشش کریں۔')}</div>`:''}`;

// Replace content without destroying lesson state or interval.
const markup=`<div class="eyebrow">${esc(tr(l.title,l.titleUr))} · ${i+1} / 5</div><div class="lesson-progress">${catalog.blocks.map((_,j)=>`<span class="${j<=i?'done':''}"></span>`).join('')}</div><h2>${esc(tr(b.title,b.titleUr))}</h2><p class="help">${b.minutes} ${tr('suggested minutes · Your timer only runs while this page is visible.','تجویز کردہ منٹ · ٹائمر صرف صفحہ کھلا ہونے پر چلتا ہے۔')}</p>${content}<div class="lesson-actions"><span class="countdown">${icon('clock')} <span id="lesson-clock">${formatTime(run.seconds)}</span> ${tr('active time','فعال وقت')}</span><div class="button-row" style="margin:0">${i?`<button class="secondary" id="prev-block">${tr('Back','پیچھے')}</button>`:''}<button class="primary green" id="next-block">${tr(i===4?'Check & finish':'Continue',i===4?'جانچیں اور مکمل کریں':'آگے بڑھیں')} ${icon('arrow')}</button></div></div>`;
const held=lessonRun;modal(markup,true);lessonRun=held;overlay.querySelector('#writing-response')?.addEventListener('input',e=>{run.writing=e.target.value;pr.drafts??={};pr.drafts[l.id]=run.writing;persistRun();});overlay.querySelector('#lesson-record')?.addEventListener('click',()=>record(overlay.querySelector('#lesson-transcript'),overlay.querySelector('#lesson-record')));overlay.querySelectorAll('[data-answer]').forEach(el=>el.onclick=()=>{run.answers[Number(el.dataset.answerIndex)]=el.dataset.answer;run.wrong=false;persistRun();showBlock();});overlay.querySelector('#prev-block')?.addEventListener('click',()=>{run.index--;persistRun();showBlock();});overlay.querySelector('#next-block').onclick=()=>{if(i<4){run.index++;persistRun();showBlock();}else if(lessonQuestions(l).some((_,j)=>!run.answers[j])){toast(tr('Choose an answer first.','پہلے جواب منتخب کریں۔'));}else if(!completeLesson(pr,l,run.answers)){run.wrong=true;showBlock();}else{const elapsed=run.seconds;save();closeModal();render();modal(`${robot()}<div class="eyebrow">${tr('ONE STEP FURTHER','ایک قدم آگے')}</div><h2>${tr('Look at you, learning!','آپ نے نیا سبق سیکھ لیا!')}</h2><p>${tr('Keep these words close. A little practice tomorrow will help them stick.','کل کی تھوڑی سی دہرائی ان الفاظ کو یاد رکھنے میں مدد دے گی۔')}</p><div class="large-stat">30 XP</div><p class="help">${tr(`30-minute planned lesson completed · ${formatTime(elapsed)} active time. Repeating a lesson does not award extra XP.`,`۳۰ منٹ کا منصوبہ بند سبق مکمل · فعال وقت ${formatTime(elapsed)}۔ دہرائی پر اضافی پوائنٹس نہیں ملتے۔`)}</p><button class="primary" data-action="close">${tr('Back to my learning','واپس میری تعلیم پر')}</button>`);if(auth)syncCloud().catch(()=>toast(tr('Saved on device. Cloud sync will retry when you choose Sync now.','آلے پر محفوظ۔ کلاؤڈ کے لیے دوبارہ سنک کریں۔')));}};}
function word(w){return `<div class="word"><div><strong dir="${lang().direction}">${esc(w.text)}</strong><small>${esc(tr(w.meaning,w.meaningUr))}</small><em>${esc(w.transliteration)}</em></div><button data-speak="${esc(w.text)}" aria-label="Listen to phrase">${icon('sound')}</button></div>`;}
function onboarding(){modal(`${robot()}<div class="eyebrow">ILMIGO DIGITAL ACADEMY</div><h2>Meet your new learning companion.</h2><p>Start small. Speak a little. Discover a bigger world with ILMIGO.<br><span lang="ur" dir="rtl">روز تھوڑا سیکھیں، اعتماد سے بولیں۔</span></p><form id="onboard"><label for="first-name">Your name / آپ کا نام</label><input id="first-name" maxlength="40" value="" placeholder="What should ILMIGO call you?" required><label for="first-ui">Explanation language / سمجھانے کی زبان</label><select id="first-ui"><option value="en">English</option><option value="ur">اردو</option></select><label for="first-course">I want to learn / میں سیکھنا چاہتا ہوں</label><select id="first-course"><option value="en">English</option><option value="ur">اردو · Urdu</option></select><label><input id="adult-check" type="checkbox" required> I’m 18+ or a parent setting this up.</label><p class="help">Children learn through a parent-managed profile. This build includes a 20-lesson English track and a 20-lesson Urdu track. Curriculum review is pending; other languages are in development.</p><button class="primary green" type="submit">Let’s begin →</button></form>`);overlay.querySelector('#onboard').onsubmit=e=>{e.preventDefault();p().name=overlay.querySelector('#first-name').value.trim()||'Learner';state.ui=overlay.querySelector('#first-ui').value;p().language=overlay.querySelector('#first-course').value;state.onboarded=true;save();closeModal();render();};}
async function profileModal(){if(state.profiles.length>=12)return toast('A family can have up to 12 profiles.');if(p().kind==='child')return toast(tr('Switch to the adult profile to manage family learners.','خاندان کے پروفائل چلانے کے لیے بالغ پروفائل منتخب کریں۔'));if(!await ensureParentPin())return;modal(`<h2>${tr('A little learner, a big world','چھوٹا سیکھنے والا، بڑی دنیا')}</h2><p>${tr('A parent manages this profile. Voice uploads and live AI are disabled for child profiles in this build.','والدین اس پروفائل کو سنبھالیں گے۔ اس ورژن میں بچوں کے لیے آواز اپ لوڈ اور براہ راست AI بند ہیں۔')}</p><form id="child-form"><label for="child-name">${tr('Nickname','مختصر نام')}</label><input id="child-name" maxlength="40" required><label for="child-age">${tr('Age range','عمر کی حد')}</label><select id="child-age"><option value="under13">Under 13 / ۱۳ سال سے کم</option><option value="13to17">13–17</option></select><label><input id="parent-consent" type="checkbox" required> ${tr('I am the parent/guardian and will supervise learning.','میں والد یا سرپرست ہوں اور نگرانی کروں گا۔')}</label><button class="primary">${tr('Create child profile','بچے کا پروفائل بنائیں')}</button></form>`);overlay.querySelector('#child-form').onsubmit=e=>{e.preventDefault();const child={id:crypto.randomUUID(),name:overlay.querySelector('#child-name').value.trim()||'Learner',kind:'child',language:p().language,goal:'School & study',completed:{},sessions:{},days:[],saved:[],reminders:false};state.profiles.push(child);save();closeModal();render();switchProfile(child.id).catch(error=>toast(error.message));};}
async function api(path,data){return sessionClient.request(path,data);}
function persistAuth(){try{if(auth)sessionStorage.setItem('ilmigo-auth',JSON.stringify(auth));else sessionStorage.removeItem('ilmigo-auth');}catch{try{sessionStorage.removeItem('ilmigo-auth');}catch{/* Storage is blocked; this page keeps its session only in memory. */}}}
function loginModal(recoverParent=false,unlockOnly=false){const recoveryOwner=recoverParent?accounts.owner:null;if(recoverParent&&!recoveryOwner)return toast(tr('Guest PINs have no verified email recovery. Use your saved PIN or restore your backup on a reset device.','مہمان پن کے لیے تصدیق شدہ ای میل نہیں۔ محفوظ پن استعمال کریں یا ری سیٹ آلے پر بیک اپ بحال کریں۔'));if(p().kind==='child'&&!recoverParent)return toast(tr('An adult must sign in from their profile.','بالغ اپنے پروفائل سے سائن ان کریں۔'));if(!config.cloud)return modal(`<h2>${tr('Your cloud is not connected yet','کلاؤڈ ابھی منسلک نہیں')}</h2><p>${tr('Email sign-in needs the owner’s Supabase configuration. You can keep learning on this device and export a backup from My space.','ای میل سائن ان کے لیے مالک کی Supabase ترتیب ضروری ہے۔ فی الحال اس آلے پر سیکھیں اور بیک اپ لیں۔')}</p><button class="primary" data-nav="family">${tr('Open my space','میری جگہ کھولیں')}</button>`);modal(`<h2>${recoverParent?tr('Recover parent access','والدین کی رسائی بحال کریں'):tr('Bring your progress along','اپنی پیش رفت ساتھ رکھیں')}</h2><p>${tr('We’ll send a sign-in code to your email.','آپ کی ای میل پر سائن ان کوڈ بھیجیں گے۔')}</p><form id="login-form"><label for="email">Email</label><input id="email" type="email" required autocomplete="email"><button class="primary" id="send-code">${tr('Send code','کوڈ بھیجیں')}</button></form><form id="verify-form" hidden><label for="otp">Email code</label><input id="otp" inputmode="numeric" required maxlength="10"><button class="primary">${tr('Verify & sign in','تصدیق اور سائن ان')}</button></form>`);let email='';overlay.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();email=overlay.querySelector('#email').value;const b=overlay.querySelector('#send-code');b.disabled=true;try{await api('/api/auth/otp',{email});overlay.querySelector('#verify-form').hidden=false;toast(tr('Check your email for the code.','ای میل پر کوڈ دیکھیں۔'));}catch(err){toast(err.message);}finally{b.disabled=false;}};overlay.querySelector('#verify-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,previousAuth=auth,previousState=state;if(form.dataset.busy)return;form.dataset.busy='true';try{const verified=await api('/api/auth/verify',{email,token:overlay.querySelector('#otp').value});if(!form.isConnected||auth!==previousAuth||state!==previousState)return;if(recoverParent){if(accounts.owner!==recoveryOwner||state.ownerId!==recoveryOwner)throw Error('Account changed. Start recovery again.');if(unlockOnly){if(verified.userId!==recoveryOwner)throw Error('Verify the parent email for this account.');const adult=state.profiles.find(pr=>pr.kind==='adult');if(!adult)throw Error('Ask the account owner to restore the family.');state.active=adult.id;}else{recoverParentAccess(state,verified.userId,deviceStorage,`${accounts.key()}:parent`);}auth=verified;persistAuth();save();closeModal();render();if(unlockOnly){await syncCloud();closeModal();render();toast(tr('Parent access restored.','والدین کی رسائی بحال ہو گئی۔'));return;}const reset=await ensureParentPin();toast(tr(reset?'Parent access recovered. New PIN saved.':'Account verified. Set a parent PIN before opening a child profile.',reset?'والدین کی رسائی بحال اور نیا پن محفوظ ہو گیا۔':'اکاؤنٹ کی تصدیق ہو گئی۔ بچے کا پروفائل کھولنے سے پہلے پن بنائیں۔'));return;}const returning=accounts.has(verified.userId);accounts.save(state);auth=verified;state=accounts.open(auth.userId);persistAuth();await syncCloud(!returning);closeModal();render();toast(tr('You’re signed in.','سائن ان ہو گیا۔'));}catch(err){if(form.isConnected)toast(err.message);}finally{delete form.dataset.busy;}};}
async function syncCloud(restore=false,consentedChildId=null){
 if(!auth)return;const session=auth,owner=auth.userId,snapshot=state;if(accounts.owner!==owner||snapshot.ownerId!==owner)throw Error('Sign in again to open your account learning space.');
 const cloud=await api('/api/sync',{profiles:restore?[]:snapshot.profiles.filter(pr=>auth.scope==='child'?pr.kind==='child'&&pr.cloudId===auth.childProfileId:pr.kind!=='child'||pr.cloudId||pr.id===consentedChildId).map(pr=>({id:pr.cloudId||null,localId:pr.id,name:pr.name,kind:pr.kind,language:pr.language,goal:pr.goal,completed:pr.completed,days:pr.days,...(pr.id===consentedChildId?{childConsent:true,childConsentVersion:config.childConsentVersion||'child-cloud-v1'}:{})}))});
 if(state!==snapshot||auth!==session||auth?.userId!==owner)return;
 if(restore&&cloud.profiles.length&&auth.scope!=='child')snapshot.profiles=[];
 for(const remote of cloud.profiles){let local=snapshot.profiles.find(pr=>pr.cloudId===remote.id)||snapshot.profiles.find(pr=>!pr.cloudId&&pr.id===remote.localId&&pr.kind===remote.kind);if(!local){const candidate=remote.localId||remote.id;local={id:snapshot.profiles.some(pr=>pr.id===candidate)?crypto.randomUUID():candidate,name:remote.name,kind:remote.kind,language:remote.language,goal:remote.goal,completed:{},sessions:{},days:[],saved:[],reminders:false};snapshot.profiles.push(local);}mergeProgress(local,remote);}
 if(auth.scope==='child'){const bound=snapshot.profiles.find(pr=>pr.kind==='child'&&pr.cloudId===auth.childProfileId);if(!bound)throw Error('Ask a parent to restore the child profile.');snapshot.active=bound.id;}
 if(!snapshot.profiles.some(pr=>pr.id===snapshot.active))snapshot.active=snapshot.profiles[0].id;
 if(typeof config!=='undefined'&&config.subscription?.enabled){try{await refreshMemberCatalog();}catch{if(state===snapshot)catalog={...catalog,lessons:[]};}}
 if(state!==snapshot||auth!==session)return;
 if(restore&&auth.scope!=='child'){snapshot.onboarded=true;const adult=snapshot.profiles.find(pr=>pr.kind==='adult');if(adult)snapshot.active=adult.id;else{const parent=emptyState().profiles[0];parent.name='Parent';snapshot.profiles.push(parent);snapshot.active=parent.id;}}save();
}

function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function reminderModal(){modal(`<h2>${tr('Make a little time for yourself','اپنے لیے تھوڑا وقت نکالیں')}</h2><p>${tr('Add a daily 30-minute learning event to your calendar. Your calendar handles notifications.','روزانہ ۳۰ منٹ کا تعلیمی وقت اپنے کیلنڈر میں شامل کریں۔')}</p><form id="reminder-form"><label for="reminder-time">${tr('Daily learning time','روز سیکھنے کا وقت')}</label><input type="time" id="reminder-time" value="18:00" required><button class="primary">${tr('Download calendar reminder','کیلنڈر یاددہانی لیں')}</button></form>`);overlay.querySelector('#reminder-form').onsubmit=e=>{e.preventDefault();const [h,m]=overlay.querySelector('#reminder-time').value.split(':');const d=new Date();d.setHours(Number(h),Number(m),0,0);if(d<new Date())d.setDate(d.getDate()+1);const stamp=d=>d.toISOString().replace(/[-:]/g,'').split('.')[0]+'Z';download('ilmigo-daily.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//ILMIGO//Daily Learning//EN','BEGIN:VEVENT',`UID:${crypto.randomUUID()}@ilmigo.local`,`DTSTAMP:${stamp(new Date())}`,`DTSTART:${stamp(d)}`,`DTEND:${stamp(new Date(d.getTime()+1800000))}`,'RRULE:FREQ=DAILY','SUMMARY:30 minutes with ILMIGO','DESCRIPTION:Open ILMIGO and continue your next language lesson.','BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY','DESCRIPTION:Time to learn with ILMIGO','END:VALARM','END:VEVENT','END:VCALENDAR',''].join('\r\n'),'text/calendar');closeModal();toast(tr('Open the downloaded file in your calendar.','ڈاؤن لوڈ کی گئی فائل کیلنڈر میں کھولیں۔'));};}
const actions={'revoke-child-sessions':async()=>{if(p().kind==='child'||!auth||auth.scope==='child')return;try{await api('/api/child-session/revoke',{confirm:true});toast(tr('Child sessions ended. Progress was kept.','بچوں کے سیشن ختم ہو گئے۔ پیش رفت محفوظ ہے۔'));}catch(error){toast(error.message);}},'recover-parent':()=>loginModal(true),'import-guest':async()=>{if(p().kind==='child'||!auth)return;if(!confirm(tr('Import this device’s guest profiles into your account? Import only data you own. Other signed-in accounts are never included.','اس آلے کے مہمان پروفائل اپنے اکاؤنٹ میں شامل کریں؟ صرف اپنا ڈیٹا شامل کریں۔')))return;try{if(!await ensureParentPin())return;const count=accounts.importGuest(state);save();render();toast(`${count} guest profiles imported. Use Sync now to back up.`);}catch(e){toast(e.message);}},close:closeModal,'switch-language':()=>navigate('languages'),reminder:reminderModal,'add-profile':profileModal,rename:()=>{if(auth?.scope==='child')return toast(tr('Ask a parent to edit the child profile.','بچے کا پروفائل بدلنے کے لیے والدین سے کہیں۔'));modal(`<h2>${tr('What should ILMIGO call you?','ILMIGO آپ کو کس نام سے بلائے؟')}</h2><form id="rename-form"><label for="new-name">${tr('Name','نام')}</label><input id="new-name" value="${esc(p().name)}" maxlength="40" required><button class="primary">${tr('Save','محفوظ کریں')}</button></form>`);overlay.querySelector('#rename-form').onsubmit=e=>{e.preventDefault();p().name=overlay.querySelector('#new-name').value.trim()||'Learner';save();closeModal();render();};},login:loginModal,logout:()=>{if(p().kind==='child')return toast('Switch to an adult profile first.');if(!save())return;auth=null;persistAuth();state=accounts.open(null);if(typeof config!=='undefined'&&config.subscription?.enabled)catalog={...catalog,lessons:[]};render();},sync:async()=>{if(p().kind==='child')return toast('Ask a parent to sync family data.');try{await syncCloud();render();toast(tr('Progress synced.','پیش رفت سنک ہو گئی۔'));}catch(err){toast(err.message);}},export:()=>{if(p().kind==='child')return toast('A parent must export family data.');download('ilmigo-progress.json',JSON.stringify(state,null,2),'application/json');},import:()=>document.querySelector('#import-file')?.click(),premium:membershipModal,privacy:()=>{if(p().kind==='child')return toast(tr('Ask a parent to manage family data from the adult profile.','خاندانی ڈیٹا سنبھالنے کے لیے والدین بالغ پروفائل استعمال کریں۔'));modal(`<h2>${tr('Your learning. Your data.','آپ کی تعلیم۔ آپ کا ڈیٹا۔')}</h2><p>${tr('Guest profiles and progress stay in browser storage. Clearing site data removes them. Export a backup first. Signed-in users can sync progress to the configured Supabase service. Microphone access is optional; browser recognition may use its provider. ILMIGO does not retain audio. AI text feedback is sent only when requested. Fonts may load from Google Fonts.','مہمان پروفائل اور پیش رفت براؤزر میں محفوظ ہیں۔ ڈیٹا مٹانے سے پہلے بیک اپ لیں۔ مائیک اختیاری ہے۔ ILMIGO آڈیو محفوظ نہیں کرتا۔ AI رہنمائی مانگنے پر متن بھیجا جاتا ہے۔')}</p><div class="button-row"><button class="secondary" id="erase-local">${tr('Erase local progress','مقامی پیش رفت مٹائیں')}</button>${auth?`<button class="secondary" id="erase-cloud">${tr('Delete cloud learning data','کلاؤڈ تعلیمی ڈیٹا مٹائیں')}</button><button class="secondary" id="erase-account">${tr('Delete account','اکاؤنٹ حذف کریں')}</button>`:''}</div><p class="help">${tr('Cloud data deletion removes profiles and progress. Account deletion also removes your email login, usage records and this account’s local learning space. Store subscriptions must be cancelled separately in your app store.','کلاؤڈ ڈیٹا حذف کرنے سے پروفائل اور پیش رفت مٹیں گے۔ اکاؤنٹ حذف کرنے سے ای میل لاگ ان بھی مٹے گا۔ سبسکرپشن اسٹور میں الگ منسوخ کریں۔')}</p>`);overlay.querySelector('#erase-local').onclick=()=>{if(!confirm(tr('Erase all learning profiles on this device? Export a backup first.','اس آلے کے تمام تعلیمی پروفائل مٹائیں؟')))return;accounts.erase();state=accounts.open(accounts.owner);closeModal();render();onboarding();};overlay.querySelector('#erase-account')?.addEventListener('click',async()=>{if(prompt('Permanently delete your account? Cloud progress will be deleted. Cancel store subscriptions separately. Type DELETE to confirm.')!=='DELETE')return;try{await api('/api/delete-account',{confirm:'DELETE'});accounts.remove(auth.userId);auth=null;persistAuth();state=accounts.open(null);closeModal();render();toast('Account and its local learning space deleted.');}catch(err){toast(err.message);}});overlay.querySelector('#erase-cloud')?.addEventListener('click',async()=>{if(!confirm('Delete all your cloud profiles and progress?'))return;try{await api('/api/delete-data',{});for(const pr of state.profiles)delete pr.cloudId;save();closeModal();toast('Cloud learning data deleted.');}catch(err){toast(err.message);}});}};
if(p().kind==='child'&&!parentGate().configured){const adult=state.profiles.find(pr=>pr.kind==='adult');if(adult)state.active=adult.id;}
render();if(!deviceStorage.persistent)toast(tr('Device storage is unavailable. Progress lasts for this session only; export a backup.','اس آلے پر مستقل اسٹوریج دستیاب نہیں۔ پیش رفت کا بیک اپ لیں۔'));if(!state.onboarded)setTimeout(onboarding,400);
window.addEventListener('online',()=>{if(auth)syncCloud().catch(()=>{});});
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});

function bindConversation(container){
 const lesson=nextLesson(catalog,p()),profile=p(),snapshot=state,owner=auth?.userId;
 let history=[],busy=false,version=0;
 const send=container.querySelector('#conversation-send'),reset=container.querySelector('#conversation-reset'),log=container.querySelector('#conversation-log');
 const valid=()=>container.isConnected&&state===snapshot&&p()===profile&&auth?.userId===owner;
 const update=()=>{send.disabled=busy||profile.kind==='child'||!lesson||history.length>=10;reset.disabled=busy;};
 update();
 reset.onclick=()=>{history=[];version++;log.replaceChildren();update();if('speechSynthesis'in window)speechSynthesis.cancel();};
 send.onclick=async()=>{
  if(busy||!lesson||profile.kind==='child')return;
  if(!auth)return loginModal();
  const input=container.querySelector('#transcript'),transcript=input.value.trim();
  if(!transcript)return toast(tr('Say or type your answer first.','پہلے اپنا جواب دیں۔'));
  const revision=version;busy=true;update();
  try{
   if(!profile.cloudId)await syncCloud();
   if(!valid())return;
   const response=await api('/api/conversation',{profileId:profile.cloudId,lessonId:lesson.id,transcript,history,ui:state.ui});
   if(!valid()||revision!==version)return;
   history.push({role:'user',content:transcript},{role:'assistant',content:response.reply});
   const turn=document.createElement('section');turn.className='feedback';
   const learner=document.createElement('p');learner.textContent=tr('You: ','آپ: ')+transcript;learner.dir=lang().direction;
   const tutor=document.createElement('p');tutor.textContent='ILMIGO: '+response.reply;tutor.dir=lang().direction;
   const explanation=document.createElement('p');explanation.textContent=response.explanation;
   const listen=document.createElement('button');listen.className='secondary';listen.textContent=tr('Listen to reply','جواب سنیں');listen.onclick=()=>{if(valid())speak(response.reply);};
   turn.append(learner,tutor,explanation,listen);log.append(turn);input.value='';
   if(history.length>=10){const note=document.createElement('p');note.textContent=tr('Five exchanges complete. Start a new conversation to practise again.','پانچ بار مشق مکمل ہوئی۔ دوبارہ مشق کے لیے نئی گفتگو شروع کریں۔');log.append(note);}
  }catch(error){if(valid())toast(error.message);}finally{busy=false;if(valid())update();}
 };
}

function stopPracticeMedia(){
 const active=recognition;recognition=null;
 if(active){active.onresult=null;active.onerror=null;active.onend=null;try{active.abort();}catch{try{active.stop();}catch{}}}
 window.speechSynthesis?.cancel();
}

async function refreshMemberCatalog(){
 if(!config.subscription?.enabled||!auth)return;
 const session=auth,owner=auth.userId,snapshot=state,learner=p();
 const remote=validateCatalog(await api('/api/member-catalog'));
 if(auth===session&&auth?.userId===owner&&state===snapshot&&p()===learner)catalog=remote;
}
async function membershipModal(){
 if(p().kind==='child')return toast(tr('A parent must manage the trial and subscription.','آزمائش اور سبسکرپشن والدین سنبھالیں۔'));
 if(!config.subscription?.enabled)return modal(`<h2>ILMIGO Plus</h2><p>${tr('US$10 per year base price, with one free 3-day trial per verified account. Owner payment setup is not activated yet. No charge can be made here.','سالانہ بنیادی قیمت 10 امریکی ڈالر، ہر تصدیق شدہ اکاؤنٹ کو ایک بار 3 دن کی مفت آزمائش۔ مالک کی ادائیگی سروس ابھی فعال نہیں۔ یہاں کوئی ادائیگی نہیں ہوگی۔')}</p><button class="primary" data-action="close">${tr('Close','بند کریں')}</button>`);
 if(!auth)return loginModal();
 const owner=auth.userId,snapshot=state,learner=p();
 try{
  const status=await api('/api/entitlements');if(auth?.userId!==owner||state!==snapshot||p()!==learner)return;
  const trial=status.trial;
  modal(`<h2>ILMIGO Plus — ${tr('annual','سالانہ')}</h2><p>${tr('US$10/year base price. Your app store shows the actual local price and taxes. A purchased subscription renews each year unless cancelled.','بنیادی قیمت سالانہ 10 امریکی ڈالر ہے۔ اصل مقامی قیمت اور ٹیکس اسٹور دکھائے گا۔ منسوخ نہ کرنے پر خریدی گئی سبسکرپشن سالانہ تجدید ہوگی۔')}</p><p>${esc(status.plus?tr('Annual subscription active.','سالانہ سبسکرپشن فعال ہے۔'):trial.active?tr('Free trial ends: ','مفت آزمائش ختم ہوگی: ')+trial.expiresAt:trial.available?tr('One free 3-day trial is available. It will not automatically charge you.','ایک بار 3 دن کی مفت آزمائش دستیاب ہے۔ اس سے خود ادائیگی نہیں ہوگی۔'):tr('Your one-time free trial has ended. Purchase in the Android or iPhone app to continue.','آپ کی ایک بار کی مفت آزمائش ختم ہو چکی ہے۔ جاری رکھنے کے لیے Android یا iPhone ایپ میں خریدیں۔'))}</p>${trial.available&&!status.plus?`<button class="primary" id="start-trial">${tr('Start my free 3-day trial','میری 3 دن کی مفت آزمائش شروع کریں')}</button>`:''}<p class="help">${tr('Web checkout is not enabled. Purchases and restoration use the Android/iPhone app store. Signing in alone never charges you.','ویب ادائیگی فعال نہیں۔ خریداری اور بحالی Android/iPhone اسٹور سے ہوگی۔ صرف سائن ان سے کوئی ادائیگی نہیں ہوتی۔')}</p><p><a href="/subscription-terms.html" target="_blank" rel="noopener">${tr('Subscription terms','سبسکرپشن کی شرائط')}</a></p><button class="secondary" data-action="close">${tr('Close','بند کریں')}</button>`);
  overlay.querySelector('#start-trial')?.addEventListener('click',async event=>{
   const button=event.currentTarget;button.disabled=true;
   try{
    if(auth?.userId!==owner||state!==snapshot||p()!==learner)return;
    await syncCloud();if(auth?.userId!==owner||state!==snapshot||p()!==learner)return;
    const result=await api('/api/trial',{profileId:learner.cloudId,confirm:true});
    if(auth?.userId!==owner||state!==snapshot||p()!==learner)return;
    if(!result.access)throw Error(tr('This account has already used its trial.','یہ اکاؤنٹ آزمائش پہلے استعمال کر چکا ہے۔'));
    await refreshMemberCatalog();if(auth?.userId!==owner||state!==snapshot||p()!==learner)return;
    closeModal();render();toast(tr('Trial started. No payment was taken.','آزمائش شروع ہو گئی۔ کوئی ادائیگی نہیں ہوئی۔'));
   }catch(error){if(auth?.userId===owner&&state===snapshot)toast(error.message);}finally{if(button.isConnected)button.disabled=false;}
  });
 }catch(error){if(auth?.userId===owner&&state===snapshot)toast(error.message);}
}

async function switchProfile(id){
 const version=++profileSwitchVersion,target=state.profiles.find(pr=>pr.id===id);
 const snapshot=state,previous=auth,active=state.active;
 const valid=()=>version===profileSwitchVersion&&state===snapshot&&auth===previous&&state.active===active&&state.profiles.includes(target);
 if(!target||target.id===active)return;
 if(previous?.scope==='child'){if(!await unlockParent()||!valid())return;return loginModal(true,true);}
 if(p().kind==='child'&&target.kind==='adult'){if(!await unlockParent()||!valid())return;}
 if(target.kind==='child'&&!parentGate().configured){if(p().kind==='child'||!await ensureParentPin()||!valid())return;}
 if(target.kind==='child'&&previous){
  if(!confirm(tr('I am this learner’s parent/guardian and consent to saving their nickname, language and progress in my family cloud account. Child AI/microphone recognition stay off. Parent access will require my PIN and email verification.','میں والد یا سرپرست ہوں اور بچے کا مختصر نام، زبان اور پیش رفت اپنے خاندانی کلاؤڈ اکاؤنٹ میں محفوظ کرنے کی اجازت دیتا ہوں۔ بچے کا AI اور مائیک بند رہیں گے۔ والدین کی رسائی کے لیے پن اور ای میل تصدیق درکار ہوگی۔')))return;
  await syncCloud(false,target.id);if(!valid())return;
  const child=await api('/api/child-session',{profileId:target.cloudId,consent:true,consentVersion:config.childConsentVersion||'child-cloud-v1'});
  if(!valid())return;
  if(child.scope!=='child'||child.userId!==previous.userId||child.childProfileId!==target.cloudId||typeof child.access_token!=='string'||!child.access_token.startsWith('ilmigo_child_'))throw Error('Child session could not be verified.');
  auth={access_token:child.access_token,userId:child.userId,scope:'child',childProfileId:child.childProfileId,expires_at:child.expires_at};persistAuth();
 }
 state.active=target.id;save();render();
 if(auth?.scope==='child'){try{await refreshMemberCatalog();if(state===snapshot&&state.active===target.id)render();}catch{/* Paid lessons stay closed until access can be verified. */}}
}
